gU_(){return"\u091c\u0935\u093e\u092c \u091c\u093f\u0938\u0947 \u0906\u092a \u092e\u0902\u091c\u093c\u0942\u0930 \u0915\u0930\u0947\u0902, \u0939\u092e\u0947\u0936\u093e"},
gTZ(){return"ReplyMate \u091c\u0935\u093e\u092c \u0938\u0941\u091d\u093e\u0924\u093e \u0939\u0948\u0964 \u0906\u092a \u0926\u0947\u0916\u0915\u0930, \u092c\u0926\u0932\u0915\u0930 \u092d\u0947\u091c\u0924\u0947 \u0939\u0948\u0902 - \u0910\u092a \u0916\u0941\u0926 \u0915\u0941\u091b \u0928\u0939\u0940\u0902 \u092d\u0947\u091c\u0924\u093e\u0964"},
gU3(){return"\u0928\u094b\u091f\u093f\u092b\u093f\u0915\u0947\u0936\u0928 \u0938\u0947 \u0939\u0940 \u0915\u093e\u092e \u0915\u0930\u0924\u093e \u0939\u0948"},
gU2(){return"\u0906\u092a\u0915\u0940 \u0905\u0928\u0941\u092e\u0924\u093f \u0938\u0947 \u092f\u0939 \u0938\u093f\u0930\u094d\u092b\u093c \u0909\u0928\u094d\u0939\u0940\u0902 \u0910\u092a\u094d\u0938 \u0915\u0947 \u0928\u094b\u091f\u093f\u092b\u093f\u0915\u0947\u0936\u0928 \u092a\u0922\u093c\u0924\u093e \u0939\u0948 \u091c\u093f\u0928\u094d\u0939\u0947\u0902 \u0906\u092a \u091a\u0941\u0928\u0924\u0947 \u0939\u0948\u0902\u0964 \u0915\u0941\u091b \u0910\u092a\u094d\u0938 \u0928\u094b\u091f\u093f\u092b\u093f\u0915\u0947\u0936\u0928 \u0915\u093e \u091f\u0947\u0915\u094d\u0938\u094d\u091f \u091b\u093f\u092a\u093e\u0924\u0947 \u092f\u093e \u091b\u094b\u091f\u093e \u0915\u0930\u0924\u0947 \u0939\u0948\u0902; \u0924\u092c ReplyMate \u0905\u0928\u0941\u092e\u093e\u0928 \u0932\u0917\u093e\u0928\u0947 \u0915\u0947 \u092c\u091c\u093e\u092f \u092c\u0924\u093e \u0926\u0947\u0924\u093e \u0939\u0948\u0964"},
gU1(){return"\u092c\u093e\u0902\u0917\u094d\u0932\u093e, \u0939\u093f\u0902\u0926\u0940 \u0914\u0930 \u0905\u0902\u0917\u094d\u0930\u0947\u091c\u093c\u0940"},
gU0(){return"\u0939\u0930 \u091c\u0935\u093e\u092c \u0915\u0940 \u092d\u093e\u0937\u093e \u0914\u0930 \u0932\u0939\u091c\u093e \u091a\u0941\u0928\u0947\u0902 - \u0926\u094b\u0938\u094d\u0924\u093e\u0928\u093e, \u0938\u0939\u091c, \u092a\u0947\u0936\u0947\u0935\u0930, \u0935\u093f\u0928\u092e\u094d\u0930, \u092e\u091c\u093c\u0947\u0926\u093e\u0930 \u092f\u093e \u091b\u094b\u091f\u093e\u0964"},
