gUX(){return"\u0907\u0938 \u092b\u093c\u094b\u0928 \u092e\u0947\u0902 \u0916\u094b\u0932\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0915\u094b\u0908 \u090f\u0915\u094d\u0938\u0947\u0938\u093f\u092c\u093f\u0932\u093f\u091f\u0940 \u0938\u094d\u0915\u094d\u0930\u0940\u0928 \u0928\u0939\u0940\u0902 \u0939\u0948\u0964 \u0938\u0947\u091f\u093f\u0902\u0917\u094d\u0938 \u2192 \u090f\u0915\u094d\u0938\u0947\u0938\u093f\u092c\u093f\u0932\u093f\u091f\u0940 \u092e\u0947\u0902 \u0926\u0947\u0916\u0947\u0902\u0964"},
gUY(){return"\u0928\u0947\u091f\u093f\u0935 \u0938\u093e\u0907\u0921 \u0938\u0947 \u0905\u092d\u0940 \u0915\u094b\u0908 \u091c\u0935\u093e\u092c \u0928\u0939\u0940\u0902 \u0906\u092f\u093e\u0964"},
